(() => {
  'use strict';
  const BASE = 'https://woongbi-quote-api.woongbts.workers.dev';
  const $ = id => document.getElementById(id);
  const won = value => Number.isFinite(Number(value)) ? Math.max(0, Math.round(Number(value))).toLocaleString('ko-KR') + '원' : '—';
  let purposeSeq = 0;
  let quickSeq = 0;
  let purposeTimer = 0;
  let applyingPurpose = false;
  let applyingQuick = false;

  async function post(path, body) {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const timeout = controller ? setTimeout(() => controller.abort(), 8000) : 0;
    try {
      const response = await fetch(BASE + path, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify(body),
        signal: controller?.signal
      });
      if (!response.ok) throw Error('recommend-api-' + response.status);
      const data = await response.json();
      if (!data || data.ok !== true) throw Error('recommend-api-invalid');
      return data;
    } finally {
      if (timeout) clearTimeout(timeout);
    }
  }

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = String(text);
    return node;
  }

  function addRow(parent, label, value, className = '') {
    const row = el('div', className);
    row.append(el('span', '', label), el('b', '', value));
    parent.append(row);
    return row;
  }

  function imageFor(device, className) {
    const src = typeof window.woongbiDeviceImage === 'function' ? window.woongbiDeviceImage(device) : '';
    if (!src) return null;
    const frame = el('div', `device-card-image ${className}`);
    const img = document.createElement('img');
    img.src = src;
    img.alt = device?.name || '휴대폰';
    img.loading = 'lazy';
    img.decoding = 'async';
    frame.append(img);
    return frame;
  }

  function dispatch(node, type) {
    node?.dispatchEvent(new Event(type, {bubbles: true}));
  }

  function openDirect(item, joinType) {
    if (!item?.d?.id || !item?.p?.id) return;
    const carrier = $('carrier');
    const join = $('join-type');
    const method = $('discount-method');
    const search = $('device-search');
    const device = $('device-select');
    const plan = $('plan-select');
    const welfare = $('welfare-type');
    if (!carrier || !join || !device || !plan) return;

    carrier.value = item.d.carrier || carrier.value;
    dispatch(carrier, 'change');
    join.value = joinType || item.joinLabel || join.value;
    dispatch(join, 'change');
    if (search) {
      search.value = item.d.name || '';
      dispatch(search, 'input');
    }
    device.value = item.d.id;
    dispatch(device, 'change');
    plan.value = item.p.id;
    dispatch(plan, 'change');
    if (method && ['support', 'contract'].includes(item.best?.method)) {
      method.value = item.best.method;
      dispatch(method, 'change');
    }
    if (welfare && item.welfare && [...welfare.options].some(option => option.value === item.welfare)) {
      welfare.value = item.welfare;
      dispatch(welfare, 'change');
    }
    if (search) search.value = '';
    document.querySelector('[data-mobile-mode="direct"]')?.click();
    setTimeout(() => $('direct-mobile-grid')?.scrollIntoView({behavior: 'smooth', block: 'start'}), 40);
  }

  const purposeNames = {senior: '효도폰', kids: '키즈폰', value: '가성비폰', premium: '프리미엄폰'};

  function purposeState() {
    const active = document.querySelector('[data-purpose-category].active');
    return {
      category: active?.dataset.purposeCategory || 'senior',
      carrier: $('purpose-carrier')?.value || 'all',
      join_type: $('purpose-join')?.value || '기기변경',
      basic_pension: Boolean($('purpose-pension')?.checked)
    };
  }

  function purposeConsult(item, category, joinType) {
    if (!item) return '';
    const method = item.kidsPromo ? '신규가입 특가' : item.best?.method === 'support' ? '공시지원금' : '선택약정 25%';
    const join = item.joinLabel || joinType || '기기변경';
    const lines = [
      '[웅비통신 용도별 추천 상담]',
      `용도: ${purposeNames[category] || '휴대폰'}`,
      `통신사: ${item.d?.carrier || '확인 필요'}`,
      `가입유형: ${join}`,
      `기종: ${item.d?.name || '확인 필요'}`,
      `요금제: ${item.p?.name || '확인 필요'} / ${won(item.p?.monthly_fee)}`,
      `추천 조건: ${method}`,
      `예상 월 납부액: ${won(item.best?.monthly)}`
    ];
    if (item.kidsPromo) lines.push('기기값: 0원 행사', '※ 신규가입 한정 · 해당 요금제 및 행사 조건 기준');
    if (item.welfare === 'basic_pension') lines.push(`기초연금 수급자 할인: -${won(item.best?.welfare?.amount || 0)}`);
    if (category === 'premium' && item.support?.known) lines.push(`공시지원금: -${won(item.support.support)}`, `지원 후 기기값: ${won(item.support.principal)}`);
    lines.push('※ 실제 가입 가능 여부·자격·지원금·프로모션은 상담 시점에 최종 확인합니다.');
    return lines.join('\n');
  }

  function premiumLineup(device) {
    const text = `${device?.name || ''} ${device?.model_code || ''}`.toLowerCase().replace(/\s+/g, '');
    if (/s26ultra/.test(text)) return '갤럭시 S26 시리즈 · Ultra';
    if (/s26\+|s26plus/.test(text)) return '갤럭시 S26 시리즈 · S26+';
    if (/갤럭시s26|galaxys26|s26/.test(text)) return '갤럭시 S26 시리즈 · S26';
    if (/폴드8|fold8/.test(text)) return '갤럭시 Z 폴더블8 · Fold8';
    if (/플립8|flip8/.test(text)) return '갤럭시 Z 폴더블8 · Flip8';
    if (/아이폰18|iphone18/.test(text)) return 'iPhone 18 시리즈';
    return '';
  }

  function renderPurpose(data, state) {
    const target = $('purpose-results');
    if (!target) return;
    applyingPurpose = true;
    const note = $('purpose-category-note');
    if (note && data.description) note.textContent = data.description;
    target.innerHTML = '';
    const items = Array.isArray(data.items) ? data.items : [];
    if (!items.length) {
      target.append(el('p', '', '현재 등록된 데이터에서 이 조건에 맞는 조합을 찾지 못했습니다. 통신사나 가입유형을 바꾸거나 직접 계산을 이용해 주세요.'));
      setTimeout(() => { applyingPurpose = false; }, 0);
      return;
    }

    items.forEach((item, index) => {
      const card = el('article', item.kidsPromo ? 'purpose-card kids-sale-card' : 'purpose-card');
      const top = el('div', 'purpose-card-top');
      const join = item.joinLabel || state.join_type || '기기변경';
      top.append(el('span', '', `${item.d?.carrier || ''} · ${join}`));
      const badge = item.kidsPromo ? (item.promoLabel || 'SALE') : item.curated ? '실제 매장 견적' : state.category === 'senior' ? (index === 0 ? '매장 추천 조합' : '추천 조합') : state.category === 'premium' ? (index === 0 ? '공시지원 중심' : '기기값 할인 조합') : '추천 조합';
      top.append(el('small', '', badge));
      card.append(top);

      const picture = imageFor(item.d, 'purpose-device-image');
      if (picture) card.append(picture);
      card.append(el('strong', '', item.d?.name || '휴대폰'));
      if (state.category === 'premium') {
        const lineup = premiumLineup(item.d);
        if (lineup) card.append(el('span', 'purpose-lineup', lineup));
      }
      card.append(el('em', '', item.p?.name || '요금제 확인'));

      if (item.kidsPromo) {
        const deal = el('div', 'kids-zero-deal');
        deal.append(el('span', '', item.promoLabel || 'SALE'), el('strong', '', item.promoText || '기기값 0원 행사'), el('small', '', '신규가입 한정 · 해당 요금제 기준'));
        card.append(deal);
      }

      const total = el('div', 'purpose-card-total');
      total.append(el('span', '', item.welfare === 'basic_pension' ? '예상 월 납부액 · 기초연금 할인 포함' : '예상 월 납부액'), el('b', '', won(item.best?.monthly)));
      card.append(total);
      card.append(el('p', 'quote-amount-note', item.kidsPromo ? '신규가입 행사 기준 · 재고와 최종 조건은 상담으로 확인' : '매장 추가지원금·가족/인터넷 결합 미반영 · 최종 조건은 상담으로 확인'));

      const specs = el('div', 'wb-v2-specs');
      [['데이터', item.p?.data], ['통화', item.p?.voice]].forEach(([label, value]) => {
        const spec = el('span');
        spec.append(el('small', '', label), el('b', '', value || '확인 필요'));
        specs.append(spec);
      });
      card.append(specs);

      const details = el('details', 'recommend-details');
      details.append(el('summary', '', '요금 구성·할인 비교 자세히 보기'));
      const body = el('div', 'recommend-details-body');
      const detail = el('div', 'purpose-card-detail');
      if ((state.category === 'premium' || state.category === 'value') && item.support?.known) {
        addRow(detail, '공시지원금', '-' + won(item.support.support));
        addRow(detail, '지원 후 기기값', won(item.support.principal));
      }
      if (item.kidsPromo) {
        addRow(detail, '기기값', '0원');
        addRow(detail, '월 통신요금', won(item.best?.service));
      } else {
        addRow(detail, '월 기기값 · 이자 포함', won(item.best?.inst?.monthly));
        addRow(detail, '할인 후 통신요금', won(item.best?.service));
      }
      if (item.welfare === 'basic_pension') addRow(detail, '기초연금 수급자 할인', '-' + won(item.best?.welfare?.amount || 0), 'welfare-line');
      body.append(detail);

      const compare = el('div', item.kidsPromo ? 'purpose-method-compare kids-sale-condition' : 'purpose-method-compare');
      if (item.kidsPromo) {
        compare.textContent = '신규가입 한정 특가 · 재고 및 행사 조건은 상담 시 최종 확인';
      } else {
        addRow(compare, '공시지원 월', item.support?.known ? won(item.support.monthly) : '매장 확인');
        addRow(compare, '선택약정 월', item.contract?.known ? won(item.contract.monthly) : '매장 확인');
      }
      body.append(compare);
      const best = item.kidsPromo
        ? `기기값 0원 행사 · ${item.p?.name || ''} 기준 월 ${won(item.best?.monthly)}`
        : state.category === 'premium' && item.support?.known
          ? `기기값 할인 중심 · 공시지원금 ${won(item.support.support)} · 지원 후 기기값 ${won(item.support.principal)}`
          : `${item.best?.method === 'support' ? '공시지원금' : '선택약정 25%'} 기준으로 계산한 월 예상금액입니다.`;
      body.append(el('div', 'purpose-best', best));
      details.append(body);
      card.append(details);

      const actions = el('div', 'purpose-card-actions');
      if (!item.kidsPromo) {
        const detailButton = el('button', '', '자세히 계산');
        detailButton.type = 'button';
        detailButton.addEventListener('click', () => openDirect(item, join));
        actions.append(detailButton);
      }
      const consult = el('button', 'primary', item.kidsPromo ? '이 특가 상담' : '이 조건 상담');
      consult.type = 'button';
      if (item.kidsPromo) consult.style.gridColumn = '1 / -1';
      consult.addEventListener('click', () => window.WoongbiQuoteHandoff?.open(purposeConsult(item, state.category, join)));
      actions.append(consult);
      card.append(actions);
      target.append(card);
    });
    document.documentElement.dataset.recommendApi = 'ready';
    setTimeout(() => { applyingPurpose = false; }, 0);
  }

  async function syncPurpose() {
    const state = purposeState();
    const run = ++purposeSeq;
    try {
      const data = await post('/recommend/purpose', state);
      if (run !== purposeSeq) return;
      renderPurpose(data, state);
    } catch {
      document.documentElement.dataset.recommendApi = 'fallback';
    }
  }

  function schedulePurpose(delay = 80) {
    clearTimeout(purposeTimer);
    purposeTimer = setTimeout(syncPurpose, delay);
  }

  function quickState() {
    return {
      carrier: $('quick-carrier')?.value || '',
      join_type: $('quick-join')?.value || '',
      brand: $('quick-brand')?.value || 'all',
      budget: $('quick-budget')?.value || 'light'
    };
  }

  function renderQuick(data, state) {
    const target = $('quick-results');
    if (!target) return;
    applyingQuick = true;
    target.innerHTML = '';
    const items = Array.isArray(data.items) ? data.items : [];
    if (!items.length) {
      target.append(el('p', '', '현재 조건에서 계산 가능한 조합을 찾지 못했습니다. 통신사·가입유형·브랜드를 한 단계 넓혀보세요.'));
      setTimeout(() => { applyingQuick = false; }, 0);
      return;
    }
    const profileLabel = data.profile?.label || '선택한 월 부담';
    const note = $('quick-budget-note');
    if (note) note.textContent = state.budget === 'any' ? '월 부담 제한 없이 현재 계산 가능한 조합을 넓게 비교합니다.' : `${profileLabel}를 중심으로 보고, 정확히 맞는 조합이 부족하면 가장 가까운 조건까지 함께 비교합니다.`;

    items.forEach(item => {
      const card = el('article', 'quick-result-card');
      const badge = el('span', 'quick-result-badge', item.badge || '추천 조합');
      card.append(badge);
      const picture = imageFor(item.d, 'quick-device-image');
      if (picture) badge.after(picture);
      card.append(el('strong', '', item.d?.name || '휴대폰'));
      card.append(el('em', '', `${item.p?.name || '요금제 확인'} · 요금제 ${won(item.p?.monthly_fee)}`));
      const specs = el('div', 'quick-plan-specs');
      [['데이터', item.p?.data], ['통화', item.p?.voice], ['문자', item.p?.sms]].forEach(([label, value]) => {
        const spec = el('span');
        spec.append(el('small', '', label), el('b', '', value || '확인 필요'));
        specs.append(spec);
      });
      card.append(specs);
      const price = el('div', 'quick-result-price');
      price.append(el('small', '', '예상 월 납부액'), el('b', '', won(item.best?.monthly)));
      card.append(price);
      const method = item.best?.method === 'support' ? '공시지원금' : '선택약정 25%';
      card.append(el('small', 'quick-result-reason', `${method} 기준 · ${item.reason || '현재 조건에 맞는 조합'}\n${item.in_band ? profileLabel : '선택 부담대에 가까운 조건'}`));
      const button = el('button', '', '이 조건으로 자세히 계산');
      button.type = 'button';
      button.addEventListener('click', () => openDirect(item, state.join_type));
      card.append(button);
      target.append(card);
    });
    document.documentElement.dataset.recommendApi = 'ready';
    setTimeout(() => { applyingQuick = false; }, 0);
  }

  async function syncQuick() {
    const state = quickState();
    if (!state.carrier || !state.join_type) return;
    const run = ++quickSeq;
    try {
      const data = await post('/recommend/quick', state);
      if (run !== quickSeq) return;
      renderQuick(data, state);
    } catch {
      document.documentElement.dataset.recommendApi = 'fallback';
    }
  }

  function init() {
    const purposeResults = $('purpose-results');
    const quickResults = $('quick-results');
    if (!purposeResults && !quickResults) return;

    document.querySelectorAll('[data-purpose-category]').forEach(button => button.addEventListener('click', () => setTimeout(() => schedulePurpose(20), 0)));
    ['purpose-carrier', 'purpose-join', 'purpose-pension'].forEach(id => $(id)?.addEventListener('change', () => schedulePurpose(20)));
    document.querySelectorAll('[data-mobile-mode]').forEach(button => button.addEventListener('click', () => {
      if (button.dataset.mobileMode === 'purpose') schedulePurpose(20);
    }));
    $('quick-find')?.addEventListener('click', () => setTimeout(syncQuick, 0));

    if (purposeResults) {
      new MutationObserver(() => {
        if (!applyingPurpose && !purposeResults.textContent.includes('불러오는 중')) schedulePurpose(100);
      }).observe(purposeResults, {childList: true, subtree: true, characterData: true});
    }
    if (quickResults) {
      new MutationObserver(() => {
        if (!applyingQuick && quickResults.querySelector('.quick-result-card')) setTimeout(syncQuick, 60);
      }).observe(quickResults, {childList: true, subtree: true, characterData: true});
    }

    schedulePurpose(1200);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, {once: true});
  else init();
})();
